def best_threshold_f1(probs, target):
    best_t, best_f1 = 0.5, -1.0
    target = target.bool()
    for t in torch.linspace(0.05, 0.95, 19, device=probs.device):
        pred = probs >= t
        tp = (pred & target).sum().float()
        fp = (pred & ~target).sum().float()
        fn = (~pred & target).sum().float()
        f1 = (2 * tp / (2 * tp + fp + fn + 1e-6)).item()
        if f1 > best_f1:
            best_t, best_f1 = t.item(), f1
    return best_t

