def mape(y_true, y_pred, eps=1e-8):
    y_true = np.asarray(y_true)
    y_pred = np.asarray(y_pred)
    denom = np.maximum(np.abs(y_true), eps)
    return np.mean(np.abs(y_true - y_pred) / denom)

def balanced_accuracy(y_true, y_pred):
    y_true = np.asarray(y_true)
    y_pred = np.asarray(y_pred)
    recall0 = ((y_true == 0) & (y_pred == 0)).sum() / max((y_true == 0).sum(), 1)
    recall1 = ((y_true == 1) & (y_pred == 1)).sum() / max((y_true == 1).sum(), 1)
    return 0.5 * (recall0 + recall1)

def logloss(y, p, eps=1e-15):
    p = np.clip(p, eps, 1 - eps)
    return -np.mean(y * np.log(p) + (1 - y) * np.log(1 - p))

def recall_at_k(recommended, relevant, k):
    relevant = set(relevant)
    if not relevant:
        return 0.0
    hits = len(set(recommended[:k]) & relevant)
    return hits / len(relevant)

def precision_at_k(recommended, relevant, k):
    if k == 0:
        return 0.0
    relevant = set(relevant)
    hits = len(set(recommended[:k]) & relevant)
    return hits / k

def mrr_at_k(recommended, relevant, k):
    relevant = set(relevant)
    for rank, item in enumerate(recommended[:k], start=1):
        if item in relevant:
            return 1.0 / rank
    return 0.0

def dcg_at_k(recommended, relevant, k):
    relevant = set(relevant)
    score = 0.0
    for rank, item in enumerate(recommended[:k], start=1):
        if item in relevant:
            score += 1.0 / np.log2(rank + 1)
    return score

def apk(recommended, relevant, k):
    relevant = set(relevant)
    if not relevant:
        return 0.0
    hits = 0
    score = 0.0
    for i, item in enumerate(recommended[:k], start=1):
        if item in relevant:
            hits += 1
            score += hits / i
    return score / min(len(relevant), k)

def binary_accuracy_from_logits(logits, target):
    pred = logits >= 0
    target = target.bool()
